export async function sincronizarFGVComplementoSjcCaragua(){
 const user=await prisma.usuario.findFirst({orderBy:{id:"asc"},select:{id:true}});
 if(!user) return {inseridas:0,existentes:0,repetidas:0};
 const norm=(s:string)=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
 const all=await prisma.questao.findMany({where:{fonte:FONTE_PROVAS_REAIS},select:{enunciado:true}});
 const hashes=new Set(all.map(x=>norm(x.enunciado)));const disciplinas=new Map<string,number>();
 let inseridas=0,existentes=0,repetidas=0;
 for(const prova of LOTES)for(const q of prova.questoes){
   if(!q.enunciado.trim()||q.alternativas.length!==5||!["A","B","C","D","E"].includes(q.correta)||
      q.alternativas.some(x=>!x.trim())||new Set(q.alternativas.map(x=>x.toLowerCase().trim())).size!==5)
      throw new Error("[sjc-caragua-complemento] Inconsistência "+prova.codigo+":"+q.numero);
   const origemId="fgv-"+prova.codigo+"-tipo1-q"+String(q.numero).padStart(2,"0");
   if(await prisma.questao.findFirst({where:{fonte:FONTE_PROVAS_REAIS,origemId},select:{id:true}})){existentes++;continue;}
   const hash=norm(q.enunciado);if(hashes.has(hash)){repetidas++;continue;}
   let disciplinaId=disciplinas.get(q.disciplina);
   if(!disciplinaId){
     let d=await prisma.disciplina.findFirst({where:{usuarioId:user.id,nome:{equals:q.disciplina,mode:"insensitive"}},select:{id:true}});
     if(!d)d=await prisma.disciplina.create({data:{usuarioId:user.id,nome:q.disciplina},select:{id:true}});
     disciplinaId=d.id;disciplinas.set(q.disciplina,disciplinaId);
   }
   await prisma.questao.create({data:{
     usuarioId:user.id,disciplinaId,tema:q.assunto,fonte:FONTE_PROVAS_REAIS,origemId,
     enunciado:q.enunciado,dificuldade:"medio",banca:"FGV",orgao:prova.orgao,ano:prova.ano,cargo:prova.cargo,fonteUrl:prova.prova,
     explicacao:"FGV, "+prova.orgao+" ("+prova.ano+"), "+prova.cargo+", Tipo 1, questão "+q.numero+
       ". Gabarito oficial definitivo: alternativa "+q.correta+". Caderno: "+prova.prova+" | Gabarito: "+prova.gabarito,
     alternativas:{create:q.alternativas.map((texto,i)=>({texto:"ABCDE"[i]+") "+texto,correta:"ABCDE"[i]===q.correta}))}
   }});hashes.add(hash);inseridas++;
 }
 console.log("[sjc-caragua-complemento] "+inseridas+" inseridas; "+existentes+" existentes; "+repetidas+" repetidas ignoradas.");
 return {inseridas,existentes,repetidas};
}
